-- Part 6 (diversification pass): MCQ top-up for contract_commercial_manager. This role was
-- sitting at exactly 30 questions (the original seeding floor per the product's diversification
-- audit), meaning a fixed 20-30 question draw would repeat a large share of the same pool across
-- repeat candidates. Adds 24 further questions on topics NOT already covered by
-- mcq_part5_contract_commercial_manager_seed.sql (verified by diffing topic lists): Variation
-- Order procedure, retention money, bond types, DAB/dispute boards, LD cap calculation,
-- back-to-back subcontracting, payment certification, DLP, termination grounds, contra charges,
-- vesting certificates. Domain grounding: FIDIC Red/Yellow Book clauses (variations, payment,
-- DAB, termination, DLP), standard commercial contract-management practice.
-- Same rotation technique as supabase/seed/mcq_questions_seed.sql. Idempotent via
-- (job_role, md5(stem_fa)) unique index.

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'contract_commercial_manager', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
